C[11492] = { { id = 11488, name = "Magisters' Terrace" }, { id = 11490, name = "The Scryer's Scryer" }, { id = 11492, name = "Hard to Kill" } }
do
    local aldor, scryer = nil, nil
    if type(GetFactionInfoByID) == "function" then
        local okA, _, _, standingA = pcall(GetFactionInfoByID, 932)
        local okS, _, _, standingS = pcall(GetFactionInfoByID, 934)
        if okA and okS then aldor, scryer = standingA, standingS end
    end
    local isScryer = type(scryer) == "number" and type(aldor) == "number" and scryer > aldor
    local isAldor = type(scryer) == "number" and type(aldor) == "number" and aldor > scryer
    local function selectChain(finalID, sequence)
        local selected = {}
        for _, id in ipairs(sequence) do
            local q = P[id]
            if q then selected[#selected + 1] = { id = id, name = q.name } end
        end
        C[finalID] = selected
    end
    for _, id in ipairs({10705, 10706}) do
        local first = isScryer and {10683,10684,10685,10686} or isAldor and {10568,10571,10574,10575} or {}
        local all = {}
        for _, v in ipairs(first) do all[#all+1] = v end
        for _, v in ipairs({10622,10628,10705}) do all[#all+1] = v end
        if id == 10706 then all[#all+1] = 10706 end
        selectChain(id, all)
    end
    local base = isScryer and {10687,10688,10689} or isAldor and {10587,10637,10640} or {}
    local altruis = {9991,9999,10001,10004,10009,10010,10011}
    for _, v in ipairs(base) do altruis[#altruis+1] = v end
    for _, v in ipairs({10641,10668,10669,10646,10649}) do altruis[#altruis+1] = v end
    selectChain(10649, altruis)
    local faction = type(UnitFactionGroup) == "function" and UnitFactionGroup("player") or "Alliance"
    local prefix = faction == "Horde" and {10623,10627,10663} or {10621,10626,10662}
    for _, endId in ipairs({10665,10666,10667,10670}) do
        local weapon = {}
        for _, v in ipairs(prefix) do weapon[#weapon+1] = v end
        weapon[#weapon+1] = 10664
        if endId == 10665 or endId == 10666 then weapon[#weapon+1] = endId
        else
           weapon[#weapon+1] = 10665
           weapon[#weapon+1] = 10666
           weapon[#weapon+1] = endId
        end
        selectChain(endId, weapon)
    end
end
